<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {requestText} from '../ui'
import {message} from 'ant-design-vue'
import {api,sessionUser} from '../api'
const props=defineProps({templateId:Number}),emit=defineEmits(['dirty']),router=useRouter()
const mode=ref('manual'),busy=ref(false),error=ref(''),notice=ref(''),kbs=ref([]),importId=ref(null),structure=ref(null),mappings=ref([]),lifecycle=ref('draft'),kbIds=ref([]),version=ref(''),tab=ref('outline'),prompt=ref(''),job=ref(null),base=ref(''),ready=ref(false)
const plan=ref({name:'',description:'',purpose:'',format:{paper:'A4',orientation:'portrait',font:'宋体',font_size_pt:12,heading_size_pt:16,line_spacing:1.5,margin_top_cm:2.5,margin_bottom_cm:2.5,margin_left_cm:2.5,margin_right_cm:2.5,cover:false,page_numbers:true,include_sources:false},sections:[{title:'背景与目标',level:1,instructions:'',target_words:400,kind:'fact',required:true,block_id:'section-0',fixed_content:''}]})
const json=computed(()=>JSON.stringify({plan:plan.value,mappings:mappings.value,kbIds:kbIds.value,lifecycle:lifecycle.value,version:version.value,importId:importId.value}))
watch(json,v=>{if(ready.value)emit('dirty',v!==base.value)})
const fields=computed(()=>structure.value?.fields||mappings.value.map(m=>({key:m.key,occurrences:[]})))
let draftTimer=null,alive=true
const draftKey=()=>`rag_template_draft_${sessionUser.value?.id}_${props.templateId||'new'}`,jobKey=()=>`rag_template_job_${sessionUser.value?.id}`
watch(json,()=>{if(!ready.value)return;clearTimeout(draftTimer);draftTimer=setTimeout(()=>{try{if(json.value===base.value)localStorage.removeItem(draftKey());else localStorage.setItem(draftKey(),JSON.stringify({value:JSON.parse(json.value),mode:mode.value,prompt:prompt.value}))}catch{/* Leave protection remains if browser storage is full. */}},600)})
async function restoreDraft(){try{const saved=JSON.parse(localStorage.getItem(draftKey())||'null');if(saved){const value=saved.value;if(value.importId&&!structure.value){const file=await api(`/api/templates/imports/${value.importId}`);structure.value=file.structure}plan.value=value.plan;mappings.value=value.mappings;kbIds.value=value.kbIds;lifecycle.value=value.lifecycle;version.value=value.version;importId.value=value.importId;mode.value=saved.mode;prompt.value=saved.prompt||'';notice.value='已恢复此浏览器中的未发布模板草稿。请核对后保存到系统。';emit('dirty',true);if(!props.templateId){const pending=JSON.parse(localStorage.getItem(jobKey())||'null');if(pending){job.value=pending.id;mode.value='ai';prompt.value=pending.prompt;notice.value+='另有已提交的AI任务，可点击继续查看结果；采用结果将替换当前编排。'}}}else if(!props.templateId){const savedJob=JSON.parse(localStorage.getItem(jobKey())||'null');if(savedJob){mode.value='ai';prompt.value=savedJob.prompt;job.value=savedJob.id;busy.value=true;await pollDesign(savedJob.id)}}}catch(e){error.value=e.message}finally{busy.value=false}}
onUnmounted(()=>{alive=false;clearTimeout(draftTimer)})
const bodyBlocks=computed(()=>structure.value?.blocks.filter(b=>b.part==='body'&&!b.table)||[])
onMounted(async()=>{try{kbs.value=await api('/api/knowledge-bases');if(props.templateId){const t=await api(`/api/report-templates/${props.templateId}`);plan.value=t.blueprint;structure.value=t.structure?.blocks?t.structure:null;importId.value=t.import_id;mappings.value=t.field_mappings;kbIds.value=t.knowledge_base_ids;mode.value=t.import_id?'docx':'manual';plan.value.sections.forEach((s,i)=>{if(!s.block_id)s.block_id=structure.value?.blocks.filter(b=>b.type==='heading')[i]?.id||`section-${i}`});notice.value=`基于 ${t.version} 创建新版本；保存不会覆盖旧版本。`}base.value=json.value;ready.value=true;await restoreDraft()}catch(e){error.value=e.message}})
function add(){plan.value.sections.push({title:'新章节',level:1,instructions:'',target_words:400,kind:'fact',required:true,block_id:'section-'+crypto.randomUUID(),fixed_content:''})}
function move(i,d){const rows=plan.value.sections;if(i+d<0||i+d>=rows.length)return;[rows[i],rows[i+d]]=[rows[i+d],rows[i]]}
function heading(block){if(plan.value.sections.some(s=>s.block_id===block.id))return;plan.value.sections.push({title:block.text.slice(0,100),level:1,instructions:'',target_words:400,kind:'fact',required:true,block_id:block.id,fixed_content:''})}
async function upload(event){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{const form=new FormData();form.append('file',file);const parsed=await api('/api/templates/import-docx',{method:'POST',body:form});structure.value=parsed.structure;importId.value=parsed.import_id;plan.value.name=file.name.replace(/\.docx$/i,'');const heads=parsed.structure.blocks.filter(b=>b.type==='heading');plan.value.sections=heads.map(h=>({title:h.text.slice(0,100),level:h.level,instructions:'',target_words:400,kind:'fact',required:true,block_id:h.id,fixed_content:''}));mappings.value=parsed.structure.fields.map(f=>({key:f.key,target:/名称|标题/.test(f.key)?'report_title':/时间|日期/.test(f.key)?'generated_at':'section',section_block_id:heads[0]?.id||'',value:'',required:false,input_type:'text'}));notice.value='原文件已保留。请核对标题、字段位置和解析警告，再发布模板。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function pollDesign(id){let current;do{await new Promise(resolve=>setTimeout(resolve,1200));if(!alive)return;current=await api(`/api/tasks/${id}`)}while(['queued','running'].includes(current.status));if(current.status!=='completed')throw new Error(current.error||'设计未完成');plan.value=current.result.blueprint;plan.value.sections.forEach((s,i)=>s.block_id=`section-${i}`);structure.value=null;importId.value=null;mappings.value=[];tab.value='outline';localStorage.removeItem(jobKey());job.value=null;notice.value='AI建议已转入统一编辑器，请核对章节及字段后保存。'}
async function design(){busy.value=true;error.value='';try{const created=await api('/api/templates/design',{method:'POST',body:JSON.stringify({prompt:prompt.value,constraints:{}})});job.value=created.job_id;localStorage.setItem(jobKey(),JSON.stringify({id:created.job_id,prompt:prompt.value}));await pollDesign(created.job_id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{const data=await api('/api/report-templates',{method:'POST',body:JSON.stringify({blueprint:plan.value,import_id:importId.value,parent_id:props.templateId||null,version:version.value,knowledge_base_ids:kbIds.value,mappings:mappings.value,lifecycle:lifecycle.value})});base.value=json.value;clearTimeout(draftTimer);localStorage.removeItem(draftKey());emit('dirty',false);router.push('/report-templates?created='+data.id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function addField(){const key=await requestText('业务字段名称（例如：项目负责人）','',{maxLength:100});if(!key)return;if(mappings.value.some(m=>m.key===key)){message.warning('此字段名称已存在');return}mappings.value.push({key,target:'user_input',section_block_id:'',value:'',required:true,input_type:'text'})}
</script>
<template><section class="author-page"><div class="author-header"><div><h2>{{templateId?'创建模板新版本':'创建报告模板'}}</h2><p>固定结构、业务字段和生成要求在同一处配置。保存草稿不会出现在普通用户的模板选择中。</p></div><button class="secondary-button" @click="router.push('/report-templates')">返回模板库</button></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="notice" class="success-banner">{{notice}}</div>
 <section v-if="!templateId" class="card author-form"><h3>从哪里开始？</h3><div class="mode-tabs"><button v-for="m in [{id:'manual',name:'手动编排'},{id:'ai',name:'自然语言设计'},{id:'docx',name:'导入Word'}]" :key="m.id" class="mode-tab" :class="{active:mode===m.id}" :disabled="busy||m.id==='docx'&&!sessionUser.system_admin" @click="mode=m.id">{{m.name}}</button></div><form v-if="mode==='ai'" @submit.prevent="design"><label class="field">描述用途、读者和希望包含的内容<textarea v-model="prompt" class="textarea" required minlength="5" maxlength="5000" placeholder="例如：面向指导老师的项目周报，包含本周进展、问题与下周计划。"/></label><button class="primary-button" :disabled="busy">{{busy?'AI设计中，完成后会显示可编辑结果…':'生成模板建议'}}</button><button v-if="job&&!busy" type="button" class="secondary-button" @click="busy=true;pollDesign(job).catch(e=>error=e.message).finally(()=>busy=false)">继续查看已有AI任务结果</button><button v-if="busy&&job" type="button" class="secondary-button" @click="api(`/api/tasks/${job}/cancel`,{method:'POST'})">取消设计任务</button></form><label v-if="mode==='docx'" class="field">选择DOCX模板<input type="file" accept=".docx" :disabled="busy" @change="upload"/></label></section>
 <section class="card author-form"><div class="form-grid"><label class="field">模板名称<input v-model="plan.name" class="input" required maxlength="100"/></label><label class="field">版本号（留空自动递增）<input v-model="version" class="input" maxlength="40" placeholder="例如：v2.0"/></label></div><label class="field">适用场景与写作目的<textarea v-model="plan.purpose" class="textarea" maxlength="2000"/></label><label class="field">模板说明<input v-model="plan.description" class="input" maxlength="1000"/></label><fieldset><legend>适用知识库（未勾选表示通用）</legend><label v-for="kb in kbs" :key="kb.id" class="check-line"><input v-model="kbIds" :value="kb.id" type="checkbox"/>{{kb.name}}</label></fieldset>
 <nav class="author-tabs"><button v-for="t in [{id:'outline',name:'章节与内容'},{id:'fields',name:'业务字段与映射'},{id:'format',name:'排版设置'},{id:'source',name:'原文件结构'}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{t.name}}</button></nav>
 <div v-if="tab==='outline'" class="outline-editor"><article v-for="(s,i) in plan.sections" :key="s.block_id" class="outline-row"><div class="toolbar"><strong>章节 {{i+1}}</strong><button class="secondary-button" :disabled="!!importId||i===0" @click="move(i,-1)">上移</button><button class="secondary-button" :disabled="!!importId||i===plan.sections.length-1" @click="move(i,1)">下移</button><button class="secondary-button" @click="plan.sections.splice(i,1)">移除章节</button></div><div class="form-grid"><label class="field">标题<input v-model="s.title" class="input" maxlength="100" required/></label><label class="field">标题级别<select v-model.number="s.level" class="select"><option v-for="n in 6" :key="n" :value="n">{{n}}级</option></select></label><label class="field">内容类型<select v-model="s.kind" class="select"><option value="fact">事实正文（严格证据核验）</option><option value="analysis">分析（明确标注推断）</option><option value="recommendation">建议（不冒充已实施）</option><option value="fixed">固定文字（人工核对）</option><option value="container">目录容器（不生成正文）</option></select></label><label class="field">目标字数<input v-model.number="s.target_words" class="input" type="number" min="50" max="3000"/></label></div><label v-if="s.kind==='fixed'" class="field">固定正文<textarea v-model="s.fixed_content" class="textarea" maxlength="10000"/></label><label v-else-if="s.kind!=='container'" class="field">本节要回答的问题与检索重点<textarea v-model="s.instructions" class="textarea" maxlength="2000"/></label><label class="check-line"><input v-model="s.required" type="checkbox"/>本节为正式报告必需内容</label></article><button class="secondary-button" :disabled="plan.sections.length>=20" @click="add">添加章节</button><p class="muted">父标题可设为“目录容器”，避免父子章节重复生成相同内容。Word导入章节保留原文位置，不支持拖动改变原件段落次序。</p></div>
 <div v-if="tab==='fields'"><p class="muted">“生成章节”字段会填入已核验正文；标题、时间、固定值及用户填写字段会实际替换文档占位符。模板固定内容须人工审阅，不当作知识库事实证据。</p><article v-for="m in mappings" :key="m.key" class="outline-row"><strong>{{m.key}}</strong><label class="field">内容来源<select v-model="m.target" class="select"><option value="section">生成章节</option><option value="user_input">创建报告时填写</option><option value="report_title">报告名称</option><option value="knowledge_base">知识库名称</option><option value="generated_at">生成时间</option><option value="period">业务日期范围</option><option value="literal">固定值</option><option value="ignore">忽略</option></select></label><label v-if="m.target==='section'" class="field">填入哪个章节<select v-model="m.section_block_id" class="select"><option disabled value="">选择章节</option><option v-for="s in plan.sections" :key="s.block_id" :value="s.block_id">{{s.title}}</option></select></label><label v-if="m.target==='literal'" class="field">固定值<input v-model="m.value" class="input" maxlength="2000"/></label><div v-if="m.target==='user_input'" class="toolbar"><label><input v-model="m.required" type="checkbox"/>必填</label><select v-model="m.input_type" class="select"><option value="text">文本</option><option value="date">日期</option><option value="number">数字</option></select></div></article><button v-if="!importId" class="secondary-button" @click="addField">添加业务字段</button><p v-if="!mappings.length" class="empty">没有占位符。普通提纲模板可添加创建报告时要填写的业务字段。</p></div>
 <div v-if="tab==='format'" class="form-grid"><label class="field">纸张<select v-model="plan.format.paper" class="select"><option>A4</option><option>Letter</option></select></label><label class="field">方向<select v-model="plan.format.orientation" class="select"><option value="portrait">竖版</option><option value="landscape">横版</option></select></label><label class="field">正文字体<select v-model="plan.format.font" class="select"><option>宋体</option><option>仿宋</option><option>等线</option><option>Arial</option></select></label><label class="field">字号<input v-model.number="plan.format.font_size_pt" class="input" type="number" min="10" max="18"/></label><label class="field">标题字号<input v-model.number="plan.format.heading_size_pt" class="input" type="number" min="12" max="28"/></label><label class="field">行距<input v-model.number="plan.format.line_spacing" class="input" type="number" min="1" max="2.5" step="0.1"/></label><label v-for="side in ['top','bottom','left','right']" :key="side" class="field">{{{top:'上',bottom:'下',left:'左',right:'右'}[side]}}页边距（cm）<input v-model.number="plan.format['margin_'+side+'_cm']" class="input" type="number" min="1" max="4" step="0.1"/></label><label class="check-line"><input v-model="plan.format.cover" type="checkbox"/>独立封面</label><label class="check-line"><input v-model="plan.format.page_numbers" type="checkbox"/>页码</label><label class="check-line"><input v-model="plan.format.include_sources" type="checkbox"/>附完整证据片段（基础引用列表始终保留）</label><p class="muted">DOCX与PDF共享结构和页面参数；PDF使用内置中文宋体类字体，不保证与Word的字形及分页逐像素一致。</p></div>
 <div v-if="tab==='source'"><p v-if="!structure" class="muted">此模板使用可编辑提纲，无原DOCX结构。</p><template v-else><div v-if="structure.warnings.length" class="warning-banner"><strong>需要核对的解析内容</strong><ul><li v-for="w in structure.warnings" :key="w">{{w}}</li></ul></div><p class="muted">复杂图形、动态域、原文件版式不保证无损重建；固定文字和表格位置会参与输出。表格结构共{{structure.tables.length}}个。</p><details v-for="b in bodyBlocks" :key="b.id"><summary>{{b.text||'空段落'}} · {{b.id}}</summary><button class="secondary-button" @click="heading(b)">作为生成章节标题</button><pre>{{b.text}}</pre></details><details><summary>查看表格与字段位置详情</summary><pre class="raw-json">{{JSON.stringify(structure.tables,null,2)}}</pre></details></template></div>
 </section><footer class="author-save"><label class="check-line">保存状态<select v-model="lifecycle" class="select"><option value="draft">模板草稿</option><option value="published">发布供生成使用</option></select></label><button class="primary-button" :disabled="busy||!plan.name.trim()||!plan.sections.length" @click="save">{{busy?'处理中…':templateId?'保存新版本':'保存模板'}}</button></footer>
</section></template>
